  registerStandardAppEventHandlers({ namespace: "HOME", appKey: "homeApp", createDefaultState: createDefaultHomeState }, (event) => ({ kits: event.kits }));

  registerEventHandler("HOME.SET_SORT", {
    action: (context: any, event: any) => ({
