        <ConnectorHandle
          key={`${id}-port-${connectorIndex}-${connector.guid}`}
          connector={connector}
          pieceId={piece.guid}
          selected={selectedConnector?.piece === piece.guid && selectedConnector?.connector === connector.guid}
          onPortClick={onPortClick}
