          const isSelected = selection.ports?.includes(portId);
          if (shouldRemove) {
            if (isSelected) {
              setSelectionAction?.({ ...selection, ports: selection.ports!.filter((i) => i !== portId) });
            }
          } else if (shouldAdd) {
            if (!isSelected) {
              setSelectionAction?.({ ...selection, ports: [...(selection.ports || []), portId] });
            }
