          const isSelected = selection.tags?.includes(tagId);
          if (shouldRemove) {
            if (isSelected) {
              setSelectionAction?.({ ...selection, tags: selection.tags!.filter((t) => t !== tagId) });
            }
          } else if (shouldAdd) {
            if (!isSelected) {
