        } else if (row.kind === "authors") {
          const authorName = (row.data as Author).name;
          const isSelected = selection.authors?.includes(authorName);
          if (shouldRemove) {
            if (isSelected) {
              setSelectionAction?.({ ...selection, authors: selection.authors!.filter((a) => a !== authorName) });
            }
          } else if (shouldAdd) {
            if (!isSelected) {
