      } else {
        actor.send({ type: "TYPE.DESELECT_CONNECTOR", kitGuid, typeGuid, connectorGuid: connectorId });
      }
    };
  }, [actor, kitGuid, typeGuid, connectorId, canSet]);
  return conditionalHookResult(canSet, value, setter);
}

