          diff.models.removed.forEach((modelId) => {
            const guid = modelId.guid;
            const index = Array.from(this.models.keys()).indexOf(guid);
            if (index !== -1) {
              this.yModels.delete(index, 1);
              this.models.delete(guid);
            }
          });
        }
