// Core reactive observation, synchronization hooks, and sketchpad store implementation.

/**
 * Creates a Yjs observer that triggers the given subscription callback on changes.
 *
 *  * [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️createobserver](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/createObserver)
 **/
export function createObserver<T>(yMap: Y.Map<T> | Y.Array<T>, subscribe: Subscribe, deep: boolean = false): Disposable {
  const callback = () => {
    subscribe(() => { });
  };
  if (deep) {
    yMap.observeDeep(callback);
    return () => yMap.unobserveDeep(callback);
  } else {
    yMap.observe(callback);
    return () => yMap.unobserve(callback);
  }
}

/**
 * Creates a Yjs field observer that tracks a single key on a Y.Map.
 *
 *  * [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️createfieldobserver](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/createFieldObserver)
 **/
export function createFieldObserver<T>(yMap: Y.Map<T>, key: string, subscribe: Subscribe, deep: boolean = false): Disposable {
  const disposables: Disposable[] = [];
  let currentValue = yMap.get(key);
  const notifySubscriber = () => subscribe(() => { });
  const setupNestedObserver = (value: any) => {
    if (deep && value instanceof Y.Map) {
      const nestedCallback = () => notifySubscriber();
      value.observeDeep(nestedCallback);
      disposables.push(() => value.unobserveDeep(nestedCallback));
    } else if (deep && value instanceof Y.Array) {
      const nestedCallback = () => notifySubscriber();
      value.observeDeep(nestedCallback);
      disposables.push(() => value.unobserveDeep(nestedCallback));
    }
  };
  if (currentValue !== undefined) setupNestedObserver(currentValue);
  const mapCallback = (event: Y.YMapEvent<T>) => {
    if (event.keysChanged.has(key)) {
      disposables.forEach((d) => d());
      disposables.length = 0;
      currentValue = yMap.get(key);
      if (currentValue !== undefined) setupNestedObserver(currentValue);
      notifySubscriber();
    }
  };
  yMap.observe(mapCallback);
  return () => {
    yMap.unobserve(mapCallback);
    disposables.forEach((d) => d());
  };
}

/**
 * Creates a Yjs observer that tracks multiple keys on a Y.Map.
 *
 *  * [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️createfieldsobserver](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/createFieldsObserver)
 **/
export function createFieldsObserver<T>(yMap: Y.Map<T>, keys: string[], subscribe: Subscribe, deep: boolean = false): Disposable {
  const disposables: Disposable[] = [];
  const keySet = new Set(keys);
  const nestedDisposables = new Map<string, Disposable[]>();
  const notifySubscriber = () => subscribe(() => { });
  const setupNestedObserver = (key: string, value: any) => {
    const keyDisposables: Disposable[] = [];
    if (deep && value instanceof Y.Map) {
      const nestedCallback = () => notifySubscriber();
      value.observeDeep(nestedCallback);
      keyDisposables.push(() => value.unobserveDeep(nestedCallback));
    } else if (deep && value instanceof Y.Array) {
      const nestedCallback = () => notifySubscriber();
      value.observeDeep(nestedCallback);
      keyDisposables.push(() => value.unobserveDeep(nestedCallback));
    }
    nestedDisposables.set(key, keyDisposables);
  };
  const cleanupNestedObserver = (key: string) => {
    const keyDisposables = nestedDisposables.get(key);
    if (keyDisposables) {
      keyDisposables.forEach((d) => d());
      nestedDisposables.delete(key);
    }
  };
  keys.forEach((key) => {
    const value = yMap.get(key);
    if (value !== undefined) setupNestedObserver(key, value);
  });
  const mapCallback = (event: Y.YMapEvent<T>) => {
    let shouldNotify = false;
    event.keysChanged.forEach((key) => {
      if (keySet.has(key)) {
        cleanupNestedObserver(key);
        const newValue = yMap.get(key);
        if (newValue !== undefined) setupNestedObserver(key, newValue);
        shouldNotify = true;
      }
    });
    if (shouldNotify) notifySubscriber();
  };
  yMap.observe(mapCallback);
  return () => {
    yMap.unobserve(mapCallback);
    nestedDisposables.forEach((keyDisposables) => keyDisposables.forEach((d) => d()));
    nestedDisposables.clear();
  };
}

/**
 * Creates a Yjs observer tracking item membership in a Y.Array.
 *
 *  * [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️createarrayitemmembershipobserver](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/createArrayItemMembershipObserver)
 **/
export function createArrayItemMembershipObserver(getYArray: () => Y.Array<string> | undefined, itemId: string, subscribe: Subscribe): Disposable {
  let wasInArray = false;
  const notifySubscriber = () => subscribe(() => { });

  const checkMembership = () => {
    const yArray = getYArray();
    return yArray ? yArray.toArray().includes(itemId) : false;
  };
  wasInArray = checkMembership();

  let arrayDisposer: Disposable | null = null;

  const setupArrayObserver = () => {
    const yArray = getYArray();
    if (!yArray) {
      arrayDisposer = null;
      return;
    }

    const arrayCallback = () => {
      const isInArray = yArray.toArray().includes(itemId);
      if (isInArray !== wasInArray) {
        wasInArray = isInArray;
        notifySubscriber();
      }
    };

    yArray.observe(arrayCallback);
    arrayDisposer = () => yArray.unobserve(arrayCallback);
  };

  setupArrayObserver();

  return () => {
    if (arrayDisposer) arrayDisposer();
  };
}

/**
 * Creates a Yjs observer tracking nested array item membership within a Y.Map.
 *
 *  * [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️performancelogcounts](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/performanceLogCounts)
 **/
export function createNestedArrayItemMembershipObserver(yMap: Y.Map<any>, mapKey: string, arrayKey: string, itemId: string, subscribe: Subscribe): Disposable {
  let wasInArray = false;
  let currentNestedMap: Y.Map<any> | undefined;
  let currentArray: Y.Array<string> | undefined;
  let nestedMapDisposer: Disposable | null = null;
  let arrayDisposer: Disposable | null = null;
  const notifySubscriber = () => subscribe(() => { });

  const checkMembership = (): boolean => {
    const nestedMap = yMap.get(mapKey) as Y.Map<any> | undefined;
    if (!nestedMap) return false;
    const arr = nestedMap.get(arrayKey) as Y.Array<string> | undefined;
    if (!arr) return false;
    return arr.toArray().includes(itemId);
  };

  const setupArrayObserver = () => {
    if (arrayDisposer) {
      arrayDisposer();
      arrayDisposer = null;
    }

    const nestedMap = yMap.get(mapKey) as Y.Map<any> | undefined;
    if (!nestedMap) return;

    const arr = nestedMap.get(arrayKey) as Y.Array<string> | undefined;
    if (!arr) return;

    currentArray = arr;

    const arrayCallback = () => {
      const isInArray = arr.toArray().includes(itemId);
      if (isInArray !== wasInArray) {
        wasInArray = isInArray;
        notifySubscriber();
      }
    };

    arr.observe(arrayCallback);
    arrayDisposer = () => arr.unobserve(arrayCallback);
  };

  const setupNestedMapObserver = () => {
    if (nestedMapDisposer) {
      nestedMapDisposer();
      nestedMapDisposer = null;
    }

    const nestedMap = yMap.get(mapKey) as Y.Map<any> | undefined;
    if (!nestedMap) return;

    currentNestedMap = nestedMap;

    const nestedMapCallback = (event: Y.YMapEvent<any>) => {
      if (event.keysChanged.has(arrayKey)) {
        const prevInArray = wasInArray;
        setupArrayObserver();
        wasInArray = checkMembership();
        if (wasInArray !== prevInArray) {
          notifySubscriber();
        }
      }
    };

    nestedMap.observe(nestedMapCallback);
    nestedMapDisposer = () => nestedMap.unobserve(nestedMapCallback);
  };

  const topLevelCallback = (event: Y.YMapEvent<any>) => {
    if (event.keysChanged.has(mapKey)) {
      const prevInArray = wasInArray;

      if (arrayDisposer) {
        arrayDisposer();
        arrayDisposer = null;
      }
      if (nestedMapDisposer) {
        nestedMapDisposer();
        nestedMapDisposer = null;
      }

      setupNestedMapObserver();
      setupArrayObserver();
      wasInArray = checkMembership();

      if (wasInArray !== prevInArray) {
        notifySubscriber();
      }
    }
  };

  wasInArray = checkMembership();
  setupNestedMapObserver();
  setupArrayObserver();
  yMap.observe(topLevelCallback);

  return () => {
    yMap.unobserve(topLevelCallback);
    if (nestedMapDisposer) nestedMapDisposer();
    if (arrayDisposer) arrayDisposer();
  };
}

// [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖apps🔖sketchpad🪨performanceloggingenabled](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Apps/s/Sketchpad/d/i/performanceLoggingEnabled)
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖store🔖apps🔖sketchpad🪨performanceloggingenabled](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Apps/s/Sketchpad/d/i/performanceLoggingEnabled)
 * performanceLoggingEnabled holds the data fields for a performanceLoggingEnabled record.
 **/
let performanceLoggingEnabled = false;
// [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖apps🔖sketchpad🪨performancelogcounts](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Apps/s/Sketchpad/d/i/performanceLogCounts)
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖store🔖apps🔖sketchpad🪨performancelogcounts](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Apps/s/Sketchpad/d/i/performanceLogCounts)
 * performanceLogCounts holds the data fields for a performanceLogCounts record.
 **/
const performanceLogCounts = new Map<string, number>();
/** performanceLogTimestamps holds the data fields for a performanceLogTimestamps record.
// [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🪨performancelogtimestamps](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/performanceLogTimestamps)
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖store🔖apps🔖sketchpad🪨performancelogtimestamps](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Apps/s/Sketchpad/d/i/performanceLogTimestamps)
 **/
const performanceLogTimestamps = new Map<string, number>();

/**
 * Enables or disables performance logging for store operations.
 *
 *  * [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️enableperformancelogging](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/enablePerformanceLogging)
 **/
export function enablePerformanceLogging(enabled: boolean = true) {
  performanceLoggingEnabled = enabled;
  if (!enabled) {
    performanceLogCounts.clear();
    performanceLogTimestamps.clear();
  }
}

/** logStateAccess holds the data fields for a logStateAccess record.
// [👤semio📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️logstateaccess](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/logStateAccess)
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖store🔖apps🔖sketchpad🪨logstateaccess](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Apps/s/Sketchpad/d/i/logStateAccess)
 **/
function logStateAccess(hookName: string, storeType: string, selectorInfo?: string) {
  if (!performanceLoggingEnabled) return;
  const key = `${hookName}:${storeType}${selectorInfo ? `:${selectorInfo}` : ""}`;
  const count = (performanceLogCounts.get(key) || 0) + 1;
  performanceLogCounts.set(key, count);
  const now = Date.now();
  const lastTime = performanceLogTimestamps.get(key) || 0;
  performanceLogTimestamps.set(key, now);
  if (now - lastTime < 100) {
    console.warn(`[PERF] Rapid re-render: ${key} (${count}x, ${now - lastTime}ms apart)`);
  }
}

/**
 * Hook synchronizing a store snapshot with React state via useSyncExternalStore.
