// [👤semio📚js🗃️sketchpad💻home🔖imports🔖types🔖homeapppluginregistration](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Home%20App%20Plugin%20Registration)
// Home app plugin and event handler registration MUST initialize XState context.

/** createDefaultHomeState holds the data fields for a createDefaultHomeState record.
// [👤semio📚js🗃️sketchpad💻home🔖imports🔖types🔖homeapppluginregistration🪨createdefaulthomestate](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Home%20App%20Plugin%20Registration/d/i/createDefaultHomeState)
 * [👤semio📚js🗃️sketchpad💻home🔖homeapppluginregistration🪨createdefaulthomestate](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Home%20App%20Plugin%20Registration/d/i/createDefaultHomeState)
 **/
const createDefaultHomeState = (): HomeState => ({
  panelVisibility: { ...EMPTY_PANEL_VISIBILITY },
  selection: undefined,
  hover: undefined,
  sortColumn: undefined,
  sortDirection: undefined,
  loadingKits: [],
});

/**
 * [👤semio📚js🗃️sketchpad💻home🔖imports🔖types🔖homeapppluginregistration🪨homeappplugin](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Home%20App%20Plugin%20Registration/d/i/homeAppPlugin)
 * homeAppPlugin holds the data fields for a homeAppPlugin record.
 **/
const homeAppPlugin: AppPlugin = {
  id: "home",
  namespace: "HOME",
  machine: {
    actions: {},
    guards: {},
    eventHandlers: {},
    selectors: {},
    createDefaultState: createDefaultHomeState,
  },
};

if (typeof window !== "undefined") {
  registerAppPlugin(homeAppPlugin);

  registerStandardAppEventHandlers({ namespace: "HOME", appKey: "homeApp", createDefaultState: createDefaultHomeState }, (event) => ({ kits: event.kits }));

  registerEventHandler("HOME.SET_SORT", {
    action: (context: any, event: any) => ({
      homeApp: { ...context.homeApp, sortColumn: event.column, sortDirection: event.direction },
    }),
  });

  registerEventHandler("HOME.SELECT_KIT", {
    action: (context: any, event: any) => {
      const kits = context.homeApp.selection?.kits || [];
      if (kits.includes(event.guid)) return {};
      return { homeApp: { ...context.homeApp, selection: { kits: [...kits, event.guid] } } };
    },
  });

  registerEventHandler("HOME.DESELECT_KIT", {
    action: (context: any, event: any) => {
      const kits = context.homeApp.selection?.kits || [];
      return { homeApp: { ...context.homeApp, selection: { kits: kits.filter((k: Guid) => k !== event.guid) } } };
}

// #endregion 🔖Home App Plugin Registration

// #region 🔖Hooks (XState-based)
// [👤semio📚js🗃️sketchpad💻home🔖hooksxstatebased](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Hooks%20(XState-based))
// XState-based hooks MUST re-export state selectors for the Home app.

// #region 🔖Table
// [👤semio📚js🗃️sketchpad💻home🔖table](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Table)
// Table window MUST display kit entries in tabular form.

// #region 🔖Details
// [👤semio📚js🗃️sketchpad💻home🔖imports🔖types🔖hooksxstatebased🔖table🔖details](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Hooks%20(XState-based)/s/Table/s/Details)
// Details panel MUST show properties of selected kits.

/**
 * Kit section component displaying selected kit properties.
 *
 *  * [👤semio📚js🗃️sketchpad💻home🔖imports🔖types🔖hooksxstatebased🔖table🔖details🪨kitsection](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Hooks%20(XState-based)/s/Table/s/Details/d/i/KitSection)
 *
 * [👤semio📚js🗃️sketchpad💻home🔖imports🔖types🔖hooksxstatebased🔖table🔖details🪨kitsection](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Hooks%20(XState-based)/s/Table/s/Details/d/i/KitSection)
 **/
export const KitSection: FC = () => {
  const home = useHome() as HomeState;
  const selection = home?.selection;
  const selectedKits = selection?.kits || [];
  if (selectedKits.length === 0) return null;
  if (selectedKits.length === 1) return <SingleKitSection kitId={selectedKits[0]} />;
  return <MultipleKitsSection kitIds={selectedKits} />;
};

// [👤semio📚js🗃️sketchpad💻home🔖imports🔖types🔖hooksxstatebased🔖table🔖details🪨singlekitsection](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Hooks%20(XState-based)/s/Table/s/Details/d/i/SingleKitSection)
 * [👤semio📚js🗃️sketchpad💻home🔖canvas🔖panels🔖right🔖details🪨singlekitsection](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Canvas/s/Panels/s/Right/s/Details/d/i/SingleKitSection)
 * SingleKitSection holds the data fields for a SingleKitSection record.
 **/
const SingleKitSection: FC<{ kitId: string }> = ({ kitId }) => {
  const kitShallows = useKitShallows();
  const kitShallow = kitShallows.find((k) => k.guid === kitId);
  if (!kitShallow) {
    return (
      <TreeItem>
        <TreeContent>
          <p className="text-sm text-muted-foreground">{useLabel("semio.sketchpad.app.kit.notFound")}</p>
        </TreeContent>
      </TreeItem>
    );
  }
  return (
    <>
      <TreeItem>
        <TreeContent>
          <Input id="semio.sketchpad.app.home.panel.details.kit.name" value={kitShallow.name} readOnly showLabel />
        </TreeContent>
      </TreeItem>
      <TreeItem>
        <TreeContent>
          <Input id="semio.sketchpad.app.home.panel.details.kit.version" value={kitShallow.version || ""} placeholder={useLabel("semio.sketchpad.app.kit.versionPlaceholder.label")} readOnly showLabel />
        </TreeContent>
      </TreeItem>
      <TreeItem>
        <TreeContent>
          <Textarea id="semio.sketchpad.app.home.panel.details.kit.description" value={kitShallow.description || ""} placeholder={useLabel("semio.sketchpad.app.kit.descriptionPlaceholder.label")} readOnly showLabel />
        </TreeContent>
      </TreeItem>
      <TreeItem>
        <TreeContent>
          <Input id="semio.sketchpad.app.home.panel.details.kit.icon" value={kitShallow.icon || ""} placeholder={useLabel("semio.sketchpad.app.kit.iconPlaceholder.label")} readOnly showLabel />
        </TreeContent>
      </TreeItem>
      <TreeItem>
        <TreeContent>
          <Input id="semio.sketchpad.app.home.panel.details.kit.image" value={kitShallow.image || ""} placeholder={useLabel("semio.sketchpad.app.kit.imagePlaceholder.label")} readOnly showLabel />
        </TreeContent>
      </TreeItem>
    </>
  );
};

// [👤semio📚js🗃️sketchpad💻home🔖details🪨multiplekitssection](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Details/d/i/MultipleKitsSection)
 * [👤semio📚js🗃️sketchpad💻home🔖canvas🔖panels🔖right🔖details🪨multiplekitssection](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Canvas/s/Panels/s/Right/s/Details/d/i/MultipleKitsSection)
 * MultipleKitsSection holds the data fields for a MultipleKitsSection record.
 **/
const MultipleKitsSection: FC<{ kitIds: string[] }> = ({ kitIds }) => {
  const kitShallows = useKitShallows();
  const kits = kitIds.map((id) => kitShallows.find((k) => k.guid === id)).filter((k) => k !== undefined) as KitShallow[];

  const getCommonValue = <T,>(getter: (kit: KitShallow) => T): T | undefined => {
    if (kits.length === 0) return undefined;
    const firstValue = getter(kits[0]);
    const allSame = kits.every((kit) => getter(kit) === firstValue);
    return allSame ? firstValue : undefined;
  };

  const commonName = getCommonValue((k) => k.name);
  const commonVersion = getCommonValue((k) => k.version);
  const commonDescription = getCommonValue((k) => k.description);
  const commonIcon = getCommonValue((k) => k.icon);
  const commonImage = getCommonValue((k) => k.image);

  return (
    <>
      <TreeItem>
        <TreeContent>
          <Input id="semio.sketchpad.app.home.panel.details.kits.name" value={commonName || ""} placeholder={commonName === undefined ? useLabel("semio.sketchpad.common.mixedValues") : undefined} readOnly showLabel />
        </TreeContent>
      </TreeItem>
      <TreeItem>
        <TreeContent>
          <Input
            id="semio.sketchpad.app.home.panel.details.kits.version"
            value={commonVersion || ""}
            placeholder={commonVersion === undefined ? useLabel("semio.sketchpad.common.mixedValues") : useLabel("semio.sketchpad.app.kit.versionPlaceholder.label")}
            readOnly
            showLabel
          />
        </TreeContent>
      </TreeItem>
      <TreeItem>
        <TreeContent>
          <Textarea
            id="semio.sketchpad.app.home.panel.details.kits.description"
            value={commonDescription || ""}
            placeholder={commonDescription === undefined ? useLabel("semio.sketchpad.common.mixedValues") : useLabel("semio.sketchpad.app.kit.descriptionPlaceholder.label")}
            readOnly
            showLabel
          />
        </TreeContent>
      </TreeItem>
      <TreeItem>
        <TreeContent>
          <Input
            id="semio.sketchpad.app.home.panel.details.kits.icon"
            value={commonIcon || ""}
            placeholder={commonIcon === undefined ? useLabel("semio.sketchpad.common.mixedValues") : useLabel("semio.sketchpad.app.kit.iconPlaceholder.label")}
            readOnly
            showLabel
          />
        </TreeContent>
      </TreeItem>
      <TreeItem>
        <TreeContent>
          <Input
            id="semio.sketchpad.app.home.panel.details.kits.image"
            value={commonImage || ""}
            placeholder={commonImage === undefined ? useLabel("semio.sketchpad.common.mixedValues") : useLabel("semio.sketchpad.app.kit.imagePlaceholder.label")}
            readOnly
        </TreeContent>
      </TreeItem>
    </>
  );
};

// #endregion 🔖Details

// #region 🔖Chat
// [👤semio📚js🗃️sketchpad💻home🔖imports🔖types🔖hooksxstatebased🔖table🔖chat](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Hooks%20(XState-based)/s/Table/s/Chat)
// Chat panel MUST show the chat placeholder content.

 * [👤semio📚js🗃️sketchpad💻home🔖canvas🔖panels🔖right🔖chat🪨chatplaceholder](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Canvas/s/Panels/s/Right/s/Chat/d/i/ChatPlaceholder)
 * ChatPlaceholder holds the data fields for a ChatPlaceholder record.
 **/
    <TreeItem>
      <TreeContent>
        <p className="text-sm text-muted-foreground">{useLabel("semio.sketchpad.panel.chat.placeholder")}</p>
      </TreeContent>
    </TreeItem>
  );
};

// #endregion 🔖Chat

// #region 🔖Settings
// [👤semio📚js🗃️sketchpad💻home🔖imports🔖types🔖hooksxstatebased🔖table🔖settings](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Hooks%20(XState-based)/s/Table/s/Settings)
// Settings panel MUST expose theme, language, device, expertise, and mode toggles.

// [👤semio📚js🗃️sketchpad💻home🔖settings🪨settingscontent](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Settings/d/i/SettingsContent)
 * [👤semio📚js🗃️sketchpad💻home🔖canvas🔖panels🔖right🔖settings🪨settingscontent](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Canvas/s/Panels/s/Right/s/Settings/d/i/SettingsContent)
 * SettingsContent holds the data fields for a SettingsContent record.
 **/
const SettingsContent: FC = () => {
  const [theme, setTheme, canSetTheme] = useTheme();
  const [language, setLanguage, canSetLanguage] = useLanguage();
  const [device, setDevice, canSetDevice] = useDevice();
  const [expertise, setExpertise, canSetExpertise] = useExpertise();
  const [mode, setMode, canSetMode] = useMode();

  const languageEnLabel = useLabel("semio.sketchpad.settings.language.en");
  const languageDeLabel = useLabel("semio.sketchpad.settings.language.de");
  const languagePlaceholder = useLabel("semio.sketchpad.app.home.settings.language.placeholder");

  return (
    <>
      <TreeItem>
        <TreeContent>
          <ToggleGroup
            id="semio.sketchpad.app.home.settings.theme"
            value={theme}
            onValueChange={(value: string) => setTheme?.(value as Theme)}
            showLabel
            kind="single"
            disabled={!canSetTheme}
            items={[
              { value: Theme.SYSTEM, id: "semio.sketchpad.settings.theme.system", icon: <MonitorIcon className="size-small" /> },
              { value: Theme.LIGHT, id: "semio.sketchpad.settings.theme.light", icon: <SunIcon className="size-small" /> },
              { value: Theme.DARK, id: "semio.sketchpad.settings.theme.dark", icon: <MoonIcon className="size-small" /> },
            ]}
          />
        </TreeContent>
      </TreeItem>
      <TreeItem>
        <TreeContent>
