 * UseDesignAppFieldOptions holds the data fields for a UseDesignAppFieldOptions record.
 **/
interface UseDesignAppFieldOptions<T, TEvent extends { type: string }> {
  createGranularSelector: GranularSelectorFactory<T>;
  fallback: T;
