  useWildcardFallback?: boolean;
}

// [👤semio📚js🗃️sketchpad💻design🔖store🔖components🛠️usedesignappfield](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Store/s/Components/d/i/useDesignAppField)
