        dragPositionRef.current = null;
        pendingPieceUpdatesRef.current = [];
        pendingSelectionRef.current = null;
        if (reactFlowInstanceRef.current) {
          reactFlowInstanceRef.current.setNodes((nodes) => nodes.map((node) => ({ ...node })));
