  componentProps?: any;
}

/**
 * [👤semio📚js🗃️sketchpad💻design🔖imports🔖panels🔖windowlibrary🪨windowtemplates](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Imports/s/Panels/s/WindowLibrary/d/i/windowTemplates)
